-- Structuur van  tabel portal.aandelen_fondsen wordt geschreven
CREATE TABLE IF NOT EXISTS `aandelen_fondsen` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `isin` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `naam` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `url` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `fondsType` enum('Aandeel','Fonds') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Fonds',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `aandelen_fondsen_isin_unique` (`isin`),
  UNIQUE KEY `aandelen_fondsen_naam_unique` (`naam`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

