-- Structuur van  tabel portal.aandelen_koersen wordt geschreven
CREATE TABLE IF NOT EXISTS `aandelen_koersen` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `fondsID` bigint unsigned NOT NULL,
  `datum` date DEFAULT NULL,
  `dagkoers` decimal(10,3) NOT NULL DEFAULT '0.000',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `aandelen_koersen_fondsid_datum_unique` (`fondsID`,`datum`),
  KEY `aandelen_koersen_fondsid_index` (`fondsID`),
  KEY `aandelen_koersen_datum_index` (`datum`),
  CONSTRAINT `aandelen_koersen_fondsid_foreign` FOREIGN KEY (`fondsID`) REFERENCES `aandelen_fondsen` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4092 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

